/// <summary>
/// CB223_PalletRounding
/// Contract class
/// </summary>
[DataContractAttribute]
class METPostPricingOrderOptimisationContract extends METSysOperationTaskDataContract
{
    str     packedQuery;
    guid    topPickingProcessId;
    NoYesId isCreditMgmtCheckBatchRun;

}

Method.Source:
/// <summary>
/// Method to check credit batch should job execute or not
/// </summary>
/// <param name = "_isCreditMgmtCheckBatchRun">NoYesId parameter value</param>
/// <returns>true or false</returns>
[ DataMember, SysOperationControlVisibilityAttribute(true),
  SysOperationLabelAttribute("@MET:MET_IsTriggerCreditBatch"),
  SysOperationHelpTextAttribute("@MET:MET_IsTriggerCreditBatchHelpText")
]
public NoYesId parmIsCreditMgmtCheckBatchRun(NoYesId _isCreditMgmtCheckBatchRun = isCreditMgmtCheckBatchRun)
{
    isCreditMgmtCheckBatchRun = _isCreditMgmtCheckBatchRun;

    return isCreditMgmtCheckBatchRun;
}

/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}

[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METPostPricingOrderOptimisationQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}
